import numpy as np
# Fit model: y = f(A) + g(A)*t^p ; test t-power by grid, with f,g as polynomials in A and 1/A
def fit(p, degs=(-2,-1,0,1,2)):
    cols=[]
    for d in degs:
        cols.append(A**d)
        cols.append(A**d*t**p)
    X=np.column_stack(cols)
    c,res,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt)
for p in [1,1.5,2,2.5,3]:
    print(p, fit(p))

