import numpy as np
from scipy.optimize import least_squares
lin_all={'1':np.ones_like(A),'A':A,'logA':np.log(A),'1/A':1/A,'A/1':A**2,'sqrtA':np.sqrt(A)}
def run(keys, nb=True):
    def model(p):
        a,b,g=p
        cols=[lin_all[k] for k in keys]+[A**a*np.exp(-b*A),np.exp(-g*A),t**2/A]
        X=np.column_stack(cols)
        c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
        return dA_dt-X@c, c
    best=None
    rng=np.random.default_rng(1)
    for i in range(25):
        p0=[rng.uniform(0,3),rng.uniform(0.5,3),rng.uniform(0.2,2)]
        try:
            sol=least_squares(lambda p: model(p)[0], p0)
            v=np.mean(sol.fun**2)/np.var(dA_dt)
            if best is None or v<best[0]: best=(v,np.round(sol.x,4),np.round(model(sol.x)[1],4))
        except Exception: pass
    return best
for keys in [['1','A','logA','1/A'],['1','logA','1/A'],['1','A','1/A'],['1','A','logA'],['A','logA','1/A'],['1','A','logA','1/A','A/1']]:
    print(keys, run(keys))
